<script setup lang="ts">
import { computed, defineAsyncComponent, onBeforeUnmount, onMounted, ref } from 'vue'
import { NConfigProvider, NSelect, NModal, NSpin, NTag, NEmpty, NProgress, zhCN, dateZhCN } from 'naive-ui'
import { api, post, download, type Book, type Case, type Evidence, type Overview, type ImportPreview, type Run, type Simulation, type Evaluation } from './api'
import Icon from './components/Icon.vue'
import BalanceChart from './components/BalanceChart.vue'
import EvidenceGraph from './components/EvidenceGraph.vue'
import FundsPanel from './components/FundsPanel.vue'
import InvestigationResult from './components/InvestigationResult.vue'
import InvestigationPolicyContext from './components/InvestigationPolicyContext.vue'
import EvidenceRequests from './components/EvidenceRequests.vue'
const ProcessEvidence=defineAsyncComponent(()=>import('./components/ProcessEvidence.vue'))
const StatementEvidence=defineAsyncComponent(()=>import('./components/StatementEvidence.vue'))
const NumericEvaluation=defineAsyncComponent(()=>import('./components/NumericEvaluation.vue'))
const RootCauseEvaluation=defineAsyncComponent(()=>import('./components/RootCauseEvaluation.vue'))
const PolicyChecks=defineAsyncComponent(()=>import('./components/PolicyChecks.vue'))
const OcrReviewPanel=defineAsyncComponent(()=>import('./components/OcrReviewPanel.vue'))
const DocumentPreview=defineAsyncComponent(()=>import('./components/DocumentPreview.vue'))
const pdfOpen=ref(false);const pdfSource=ref<{documentId:string;name:string;extracted:{page:number;text:string;status:string}[]}>()
function previewPdf(doc:Record<string,unknown>){pdfSource.value={documentId:String(doc.id),name:String(doc.name),extracted:Array.isArray(doc.extracted)?doc.extracted:[]};pdfOpen.value=true}

const theme={common:{primaryColor:'#246454',primaryColorHover:'#367d6a',primaryColorPressed:'#173f36',borderRadius:'6px',fontFamily:'"Microsoft YaHei", "PingFang SC", sans-serif',textColorBase:'#253c35'},Select:{peers:{InternalSelection:{borderRadius:'6px'}}}}
const pages=[{id:'dashboard',label:'月结工作台',icon:'grid',sub:'从差异出发，让每一个结论都有依据。'},{id:'books',label:'账套与政策',icon:'book',sub:'固定适用制度、会计期间与规则版本。'},{id:'imports',label:'数据接入',icon:'upload',sub:'保留原始来源，校验后再进入账套。'},{id:'cases',label:'异常调查',icon:'search',sub:'提出解释，查找反证，在证据边界内判断。'},{id:'evidence',label:'证据浏览',icon:'link',sub:'每条引用都能返回当时可见的原始记录。'},{id:'process',label:'采购流程证据',icon:'layers',sub:'从真实采购日志出发，按来源定位每一个事件。'},{id:'statements',label:'年报证据',icon:'file',sub:'查看合并报表观察，沿页码与单元格回查原文。'},{id:'simulation',label:'模拟处理',icon:'sliders',sub:'先验证处理影响，原始账簿始终保持只读。'},{id:'reviews',label:'复核底稿',icon:'file',sub:'把事实、依据、计算与未决事项一起留存。'},{id:'evaluations',label:'评测中心',icon:'chart',sub:'用可重复实验检验效果，也保留失败结果。'}]
interface MatchResult { candidates:Record<string,unknown>[];partial_candidates:Record<string,unknown>[];unmatched:{left:string[];right:string[]};status:string;backend:string;limited_groups:Record<string,unknown>[];note:string }
const matchFlow=ref('payable');const matchResult=ref<MatchResult>();const bankFindings=ref<Record<string,unknown>[]>();
const page=ref('dashboard');const currentPage=computed(()=>pages.find(p=>p.id===page.value)!);const mobileNav=ref(false)
const mobileViewport=ref(false);let navigationMedia:MediaQueryList|undefined
function syncNavigationViewport(){mobileViewport.value=navigationMedia?.matches??false;if(!mobileViewport.value)mobileNav.value=false}
const books=ref<Book[]>([]);const bookId=ref<string|null>(null);const book=computed(()=>books.value.find(b=>b.id===bookId.value));const overview=ref<Overview>();const cases=ref<Case[]>([]);const records=ref<Record<string,unknown>[]>([]);const documents=ref<Record<string,unknown>[]>([]);const imports=ref<ImportPreview[]>([]);const policies=ref<Record<string,unknown>[]>([]);const evaluations=ref<Evaluation>();const health=ref<{status:string;mode:string;model_configured:boolean}>();const settings=ref<Record<string,unknown>>({});const loading=ref(false);const busy=ref('');const error=ref('');const notice=ref('');const query=ref('');const showHistory=ref(false)
const selectedId=ref<string|null>(null);const selectedCase=ref<Case & {stale?:boolean}>();const evidence=ref<Evidence[]>([]);const focusedEvidence=ref<Evidence>();const simulations=ref<Simulation[]>([]);const run=ref<Run>();const investigationMode=ref('rules');let stream:EventSource|undefined;let polling:ReturnType<typeof setInterval>|undefined
const bookOptions=computed(()=>books.value.map(b=>({label:b.name,value:b.id})));const caseOptions=computed(()=>cases.value.map(c=>({label:c.title,value:c.id})));const latestCases=computed(()=>cases.value.filter(c=>c.snapshot_id===overview.value?.latest_snapshot_id));const filteredCases=computed(()=>(showHistory.value?cases.value:latestCases.value).filter(c=>`${c.title} ${c.rule_id} ${c.explanation}`.toLowerCase().includes(query.value.toLowerCase())));const openCount=computed(()=>latestCases.value.filter(c=>!['normal','refuted','accepted'].includes(c.status)).length);const availableCount=computed(()=>overview.value?.capabilities.filter(c=>c.available).length||0)
const showBookModal=ref(false);const editingBook=ref(false);const bookForm=ref({name:'',framework:'CAS' as 'CAS'|'SCAS',period:'2026-09',currency:'CNY',accounts:'1002,1122,1405,2202,6001,6602',locked_periods:''});const preview=ref<ImportPreview>();const mapping=ref<Record<string,string>>({});const selectedFile=ref<File>();const fileInput=ref<HTMLInputElement>();const reviewForm=ref({decision:'reserved',comment:''});const adjustmentRows=ref([{voucher_id:'SIM-001',account:'2202',debit:'0.00',credit:'0.00',business_date:'2026-09-30',period:'2026-09',description:'模拟调整草稿'}]);const simulation=ref<Simulation>();const detailOpen=ref(false)
const fieldLabels:Record<string,string>={source_id:'来源编号',kind:'记录类型',business_date:'业务日期',period:'会计期间',currency:'币种',counterparty:'交易对手',reference:'参考编号',order_id:'订单号',invoice_id:'发票号',voucher_id:'凭证号',account:'科目',debit:'借方金额',credit:'贷方金额',amount:'业务金额',description:'摘要',direction:'收付方向'}
const statusNames:Record<string,string>={supported:'证据支持',normal:'正常差异',refuted:'正常差异',insufficient:'证据不足',unresolved:'证据不足',unsupported:'超出支持范围',open:'待调查',pending:'待处理',queued:'排队中',running:'调查中',complete:'已完成',completed:'已完成',failed:'运行失败',budget_exhausted:'预算耗尽',accepted:'已接受',returned:'已退回',reserved:'保留意见',preview:'待确认',confirmed:'已导入',needs_evidence:'待补证',incomplete:'未完成',experimental:'实验性',verified:'已验证',not_supported:'未支持',high:'高',medium:'中',low:'低',warning:'提示',info:'信息'}
const kindNames:Record<string,string>={journal:'会计分录',bank:'银行流水',order:'采购订单',receipt:'收货记录',invoice:'发票',opening:'期初余额',trial_balance:'试算平衡'}
const status=(s:unknown)=>statusNames[String(s)]||String(s||'—');const framework=(s:unknown)=>s==='SCAS'?'小企业会计准则':'企业会计准则';const short=(s:unknown)=>String(s||'—').slice(0,10);const show=(v:unknown):string=>v==null?'—':typeof v==='object'?JSON.stringify(v,null,2):String(v);const money=(v:unknown)=>{const raw=String(v??'0.00');const [integer,decimal='00']=raw.split('.');return `${integer.replace(/\B(?=(\d{3})+(?!\d))/g,',')}.${decimal.padEnd(2,'0')}`};const isWorking=computed(()=>!!run.value&&['queued','running'].includes(run.value.status));const isStale=computed(()=>!!selectedCase.value?.stale);const currentSim=computed(()=>simulation.value||simulations.value.at(-1));const simAccounts=computed(()=>Object.keys(currentSim.value?.after||{}));const tone=(s:unknown)=>['high','failed','unsupported','returned'].includes(String(s))?'danger':['normal','supported','complete','completed','confirmed','accepted','verified'].includes(String(s))?'success':'warning'
const modeNames:Record<string,string>={rules:"\u89c4\u5219",single:"\u5355 Agent",multi:"Multi-Agent",active:"\u4e3b\u52a8\u8c03\u67e5"}
const runOptions=computed(()=>(selectedCase.value?.runs||[]).map(r=>({value:r.id,label:`${modeNames[r.mode||"rules"]||r.mode} / ${status(r.status)} / ${r.created_at?.slice(0,19).replace("T"," ")||""} / ${short(r.id)}`})))
function selectRun(id:string){const chosen=selectedCase.value?.runs?.find(r=>r.id===id);if(!chosen)return;stopStream();run.value=chosen;error.value="";if(["queued","running"].includes(chosen.status))watchRun(id)}
function go(id:string){page.value=id;mobileNav.value=false;error.value=''}
async function action(name:string,fn:()=>Promise<unknown>,success?:string){if(busy.value)return;busy.value=name;error.value='';notice.value='';try{await fn();if(success)notice.value=success}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=''}}
async function loadGlobal(){const results=await Promise.allSettled([api<Book[]>('/books'),api<typeof health.value>('/health'),api<Record<string,unknown>[]>('/policies'),api<Evaluation>('/evaluations'),api<Record<string,unknown>>('/settings')]);const [b,h,p,e,s]=results;if(b.status==='fulfilled')books.value=b.value;else throw b.reason;if(h.status==='fulfilled')health.value=h.value;if(p.status==='fulfilled')policies.value=p.value;if(e.status==='fulfilled')evaluations.value=e.value;if(s.status==='fulfilled')settings.value=s.value}
async function refreshBook(){if(!bookId.value)return;const id=bookId.value;const result=await Promise.all([api<Overview>(`/books/${id}/overview`),api<Case[]>(`/cases?book_id=${id}`),api<ImportPreview[]>(`/books/${id}/imports`),api<Record<string,unknown>[]>(`/books/${id}/records`),api<Record<string,unknown>[]>(`/books/${id}/documents`)]);if(id!==bookId.value)return;[overview.value,cases.value,imports.value,records.value,documents.value]=result;if(selectedId.value&&cases.value.some(c=>c.id===selectedId.value))await loadCase(selectedId.value)}
function resetBookContext(){stopStream();selectedId.value=null;selectedCase.value=undefined;evidence.value=[];focusedEvidence.value=undefined;detailOpen.value=false;pdfOpen.value=false;pdfSource.value=undefined;overview.value=undefined;cases.value=[];records.value=[];documents.value=[];imports.value=[];preview.value=undefined;selectedFile.value=undefined;simulation.value=undefined;simulations.value=[];run.value=undefined;reviewForm.value={decision:'reserved',comment:''};resetAdjustment()}
async function changeBook(id:string){bookId.value=id;localStorage.setItem('ledgerlens.book',id);resetBookContext();await action('切换账套',refreshBook)}
async function initialize(){loading.value=true;try{await loadGlobal();const stored=new URLSearchParams(location.search).get('book')||localStorage.getItem('ledgerlens.book');bookId.value=books.value.find(b=>b.id===stored)?.id||books.value[0]?.id||null;if(bookId.value){await refreshBook();const params=new URLSearchParams(location.search);const caseId=params.get("case");if(caseId&&cases.value.some(c=>c.id===caseId)){await loadCase(caseId);go("cases");const runId=params.get("run");if(runId)selectRun(runId)}}}catch(e){error.value=`无法连接服务：${e instanceof Error?e.message:String(e)}。请检查本地后端是否运行。`}finally{loading.value=false}}
function openBook(edit=false){editingBook.value=edit;if(edit&&book.value)bookForm.value={name:book.value.name,framework:book.value.framework,period:book.value.period,currency:'CNY',accounts:book.value.accounts.join(','),locked_periods:book.value.locked_periods.join(',')};else bookForm.value={name:'',framework:'CAS',period:'2026-09',currency:'CNY',accounts:'1002,1122,1405,2202,6001,6602',locked_periods:''};showBookModal.value=true}
async function saveBook(){await action('保存账套',async()=>{const f=bookForm.value;if(!f.name.trim())throw new Error('请填写账套名称');const body={...f,accounts:f.accounts.split(/[,，\s]+/).filter(Boolean),locked_periods:f.locked_periods.split(/[,，\s]+/).filter(Boolean)};const b=editingBook.value?await api<Book>(`/books/${bookId.value}`,{method:'PUT',body:JSON.stringify(body)}):await post<Book>('/books',body);showBookModal.value=false;await loadGlobal();bookId.value=b.id;localStorage.setItem('ledgerlens.book',b.id);if(!editingBook.value)resetBookContext();await refreshBook()},editingBook.value?'政策已保存为新版本。':'账套已建立，可以开始导入资料。')}
async function seed(supplement=false){if(!bookId.value)return;await action(supplement?'补充合成资料':'载入演示账套',async()=>{await post(`/books/${bookId.value}/${supplement?'supplement-demo':'demo'}`);await refreshBook()},supplement?'已加入迟到收货资料并创建新快照，请重新执行检查。':'合成账套已载入。请执行月结检查，生成真实计算的异常案件。')}
async function check(){if(!bookId.value)return;await action('执行月结检查',async()=>{const snapshot=await post<{id:string}>('/snapshots',{book_id:bookId.value});await post('/check-runs',{book_id:bookId.value,snapshot_id:snapshot.id});await refreshBook()},'检查已完成，结果来自当前数据快照。')}
async function loadCase(id:string){stopStream();const [c,e,s]=await Promise.all([api<Case & {stale?:boolean}>(`/cases/${id}`),api<Evidence[]>(`/cases/${id}/evidence`),api<Simulation[]>(`/simulations?case_id=${id}`)]);if(selectedId.value!==id)resetAdjustment();selectedId.value=id;selectedCase.value=c;evidence.value=e;simulations.value=s;simulation.value=undefined;focusedEvidence.value=e[0];run.value=c.runs?.[0];reviewForm.value={decision:'reserved',comment:''};if(run.value&&['queued','running'].includes(run.value.status))watchRun(run.value.id)}
async function pickCase(id:string,target='cases'){await action('加载案件',async()=>{await loadCase(id);go(target)})}
function stopStream(){stream?.close();stream=undefined;if(polling){clearInterval(polling);polling=undefined}}
async function refreshRunEvidence(id:string){const caseId=selectedId.value,currentBook=bookId.value;if(!caseId)return;const fresh=await api<Evidence[]>(`/cases/${caseId}/evidence`);if(selectedId.value===caseId&&bookId.value===currentBook&&run.value?.id===id){evidence.value=fresh;if(focusedEvidence.value)focusedEvidence.value=fresh.find(row=>row.id===focusedEvidence.value?.id)}}
function watchRun(id:string){stopStream();const update=(r:Run)=>{if(run.value?.id!==id)return;run.value=r;if(selectedCase.value){const history=selectedCase.value.runs||[];selectedCase.value.runs=[r,...history.filter(previous=>previous.id!==r.id)]}if(!['queued','running'].includes(r.status)){stopStream();void refreshRunEvidence(id).catch(failure=>{if(run.value?.id===id)error.value=String(failure)});if(r.error)error.value=show(r.error)}};stream=new EventSource(`/api/v1/runs/${id}/events`);stream.onmessage=e=>{try{update(JSON.parse(e.data))}catch{error.value='运行进度解析失败，请手动刷新状态。'}};stream.onerror=()=>{stream?.close();stream=undefined;if(!polling)polling=setInterval(()=>api<Run>(`/runs/${id}`).then(update).catch(e=>{error.value=String(e);stopStream()}),2000)}}
async function investigate(){if(!selectedId.value)return;await action('启动调查',async()=>{run.value=await post<Run>(`/cases/${selectedId.value}/investigate`,{mode:investigationMode.value});watchRun(run.value.id);void refreshRunEvidence(run.value.id).catch(failure=>{if(selectedId.value)error.value=String(failure)})})}
function fileChanged(event:Event){selectedFile.value=(event.target as HTMLInputElement).files?.[0];preview.value=undefined}
async function upload(){if(!selectedFile.value||!bookId.value)return;await action('解析文件',async()=>{const form=new FormData();form.append('book_id',bookId.value!);form.append('file',selectedFile.value!);preview.value=await api<ImportPreview>('/imports',{method:'POST',body:form});mapping.value={...preview.value.mapping};await refreshBook()})}
async function remap(){if(!preview.value)return;await action('重新校验映射',async()=>{preview.value=await api<ImportPreview>(`/imports/${preview.value!.id}/mapping`,{method:'PUT',body:JSON.stringify(Object.fromEntries(Object.entries(mapping.value).filter(([,v])=>v)))});await refreshBook()})}
async function acceptOcrPreview(value:ImportPreview){preview.value=value;mapping.value={};await refreshBook()}
const previewDisplayRows=computed(()=>preview.value?.rows.map(row=>preview.value?.mapping._origin==='ocr_human_review'?row.record as Record<string,unknown>:row)||[])
const previewDisplayColumns=computed(()=>preview.value?.mapping._origin==='ocr_human_review'?Object.keys(fieldLabels).filter(key=>previewDisplayRows.value.some(row=>row[key]!==undefined&&row[key]!==null&&row[key]!=='')):Object.keys(previewDisplayRows.value[0]||{}).slice(0,8))
async function confirmImport(){if(!preview.value)return;await action('确认导入',async()=>{const r=await post<{imported:number;duplicate_count:number}>(`/imports/${preview.value!.id}/confirm`);notice.value=`成功导入 ${r.imported} 条记录，跳过 ${r.duplicate_count} 条重复来源。`;preview.value=undefined;selectedFile.value=undefined;if(fileInput.value)fileInput.value.value='';await refreshBook()})}
const simulationLink=ref({invoice_id:'',order_id:'',counterparty:''})
function resetAdjustment(){const p=book.value?.period||'2026-09';adjustmentRows.value=[{voucher_id:'SIM-001',account:'2202',debit:'0.00',credit:'0.00',business_date:`${p}-28`,period:p,description:'模拟调整草稿'}];simulationLink.value={invoice_id:'',order_id:'',counterparty:''}}
function beginSimulation(){go('simulation');simulation.value=undefined;resetAdjustment();addAdjustment()}
function addAdjustment(){const p=book.value?.period||'2026-09';adjustmentRows.value.push({voucher_id:'SIM-001',account:'',debit:'0.00',credit:'0.00',business_date:`${p}-28`,period:p,description:'模拟调整草稿'})}
async function simulate(){if(!selectedId.value)return;await action('计算模拟影响',async()=>{simulation.value=await post<Simulation>('/simulations',{case_id:selectedId.value,adjustments:adjustmentRows.value.map(row=>({...row,...simulationLink.value}))});simulations.value=await api<Simulation[]>(`/simulations?case_id=${selectedId.value}`)},'模拟已计算；请检查约束结果与政策提示。')}
async function review(){if(!selectedCase.value)return;await action('保存复核意见',async()=>{await post('/reviews',{case_id:selectedId.value,expected_snapshot_id:selectedCase.value!.snapshot_id,...reviewForm.value});await loadCase(selectedId.value!)},'复核意见已保存，并绑定当前案件快照。')}
async function exportReport(format='markdown'){if(!selectedId.value)return;await action('导出底稿',()=>download(`/exports/cases/${selectedId.value}?format=${format}`,`账证智核-${short(selectedId.value)}.${format==='json'?'json':'md'}`),'复核底稿已生成。')}
async function evaluate(){await action('运行规则评测',async()=>{await post('/evaluations/run',{mode:'rules'});evaluations.value=await api<Evaluation>('/evaluations')},'规则基准已完成，完整结果与限制见下方。')}
async function matchFunds(){if(!bookId.value)return;await action('匹配资金与往来',async()=>{matchResult.value=await api<MatchResult>(`/books/${bookId.value}/matches?flow=${matchFlow.value}`)})}
async function reconcileBank(){if(!bookId.value)return;await action('核对银行账面',async()=>{bankFindings.value=await api<Record<string,unknown>[]>(`/books/${bookId.value}/bank-reconciliation`)})}
function inspectEvidence(e:Evidence){focusedEvidence.value=e;detailOpen.value=true}
onMounted(()=>{navigationMedia=window.matchMedia('(max-width:760px)');syncNavigationViewport();navigationMedia.addEventListener('change',syncNavigationViewport);initialize()})
onBeforeUnmount(()=>{stopStream();navigationMedia?.removeEventListener('change',syncNavigationViewport)})
</script>

<template>
<NConfigProvider :theme-overrides="theme" :locale="zhCN" :date-locale="dateZhCN">
 <div class="app-shell">
  <aside id="workspace-navigation" class="sidebar" :class="{shown:mobileNav}" :inert="mobileViewport&&!mobileNav" :aria-hidden="mobileViewport&&!mobileNav?true:undefined" @keydown.esc="mobileNav=false">
   <a class="brand" href="#" @click.prevent="go('dashboard')"><span class="brand-mark"><i></i><i></i><i></i></span><span><strong>账证智核</strong><small>LEDGERLENS</small></span></a>
   <div class="workspace-label">复核工作空间 <span>LOCAL</span></div>
   <nav aria-label="主导航"><button v-for="(p,index) in pages" :key="p.id" :aria-label="p.label" :class="['nav-item',{active:page===p.id}]" @click="go(p.id)"><Icon :name="p.icon" :size="18"/><span>{{ p.label }}</span><span v-if="p.id==='cases'&&openCount" class="nav-count">{{ openCount }}</span><span v-else class="nav-index">{{ String(index+1).padStart(2,'0') }}</span></button></nav>
   <div class="sidebar-footer"><div class="local-status"><span :class="['status-dot',{offline:!health}]"/>{{ health?'本地服务已连接':'等待本地服务' }}</div><div class="sidebar-note"><Icon name="shield" :size="15"/><span>原账只读 · 调整先模拟</span></div><div class="version">研究与辅助平台 <span>v0.1</span></div></div>
  </aside>
  <div v-if="mobileNav" class="nav-backdrop" @click="mobileNav=false"/>
  <main>
   <header class="topbar"><button class="icon-button mobile-toggle" aria-label="打开导航" aria-controls="workspace-navigation" :aria-expanded="mobileNav" @click="mobileNav=!mobileNav"><Icon name="menu"/></button><div class="breadcrumb">工作空间 <span>/</span> {{ currentPage.label }}</div><div class="topbar-right"><span class="local-pill"><span class="status-dot"/>本地部署</span><span class="model-state">{{ health?.model_configured?'DeepSeek 已配置':'规则模式可用' }}</span><button class="icon-button" aria-label="刷新数据" :disabled="!!busy||loading" @click="action('刷新数据',async()=>{await loadGlobal();await refreshBook()})"><Icon name="refresh" :size="17"/></button><div class="avatar" title="本地工作空间">核</div></div></header>
   <section v-if="!['process','statements'].includes(page)" class="workspace-bar"><div class="book-picker"><span class="label-small">当前账套</span><NSelect :value="bookId" :options="bookOptions" placeholder="选择或新建账套" :disabled="!!busy||loading" @update:value="changeBook"/><button class="icon-button outline" title="新建账套" aria-label="新建账套" @click="openBook()"><Icon name="plus" :size="17"/></button></div><div class="book-meta"><span><Icon name="clock" :size="14"/>{{ book?.period||'未选择期间' }}</span><span>{{ book?framework(book.framework):'准则未配置' }}</span><span v-if="book" class="mono">政策 v{{ book.version }}</span></div></section>
   <div class="page-content">
    <div v-if="error" class="notice error" role="alert"><Icon name="info"/><span>{{ error }}</span><button aria-label="关闭错误" @click="error=''"><Icon name="close" :size="16"/></button></div>
    <div v-if="notice" class="notice success" role="status"><Icon name="check"/><span>{{ notice }}</span><button aria-label="关闭提示" @click="notice=''"><Icon name="close" :size="16"/></button></div>
    <div class="page-heading"><div><div class="eyebrow">{{ page==='dashboard'?'CLOSE WITH CONFIDENCE':'EVIDENCE BEFORE CONCLUSION' }}</div><h1>{{ currentPage.label }}<span v-if="page==='dashboard'&&book">{{ book.period.replace('-',' / ') }}</span></h1><p>{{ currentPage.sub }}</p></div><div class="heading-actions"><span v-if="busy" class="working"><NSpin :size="14"/>{{ busy }}</span><template v-if="page==='dashboard'"><button class="button" :disabled="!bookId||!!busy" @click="go('imports')"><Icon name="upload" :size="16"/>导入资料</button><button class="button primary" :disabled="!bookId||!!busy||!overview?.counts.records" @click="check"><Icon name="check" :size="16"/>执行月结检查</button></template><button v-if="page==='books'" class="button primary" @click="openBook()"><Icon name="plus" :size="16"/>新建账套</button><button v-if="page==='evaluations'" class="button primary" :disabled="!!busy" @click="evaluate"><Icon name="chart" :size="16"/>运行规则基准</button></div></div>
    <div v-if="loading" class="loading-panel"><NSpin size="large"/><p>正在连接工作空间…</p></div>
    <template v-else>
     <ProcessEvidence v-if="page==='process'"/>
     <StatementEvidence v-else-if="page==='statements'"/>
     <section v-else-if="!bookId&&page!=='evaluations'" class="welcome-panel"><div class="welcome-drawing"><span>借</span><i></i><span>贷</span><Icon name="check" :size="28"/></div><div class="eyebrow">YOUR FIRST WORKSPACE</div><h2>让账、证与结论建立联系。</h2><p>建立账套后，导入自己的资料，或载入一份明确标记的合成账套。<br/>从真实规则检查开始，逐步走完调查、模拟和复核。</p><button class="button primary" @click="openBook()"><Icon name="plus" :size="16"/>建立第一个账套</button><div class="welcome-steps"><span><b>01</b>导入与校验</span><Icon name="arrow"/><span><b>02</b>调查与取证</span><Icon name="arrow"/><span><b>03</b>模拟与复核</span></div></section>

     <template v-else-if="page==='dashboard'">
      <div class="metrics-strip"><div class="metric"><span>可见业务记录 <Icon name="layers" :size="16"/></span><strong>{{ overview?.counts.records??0 }}<small>条</small></strong><p>保留原始记录与来源定位</p></div><div class="metric"><span>当前快照异常 <Icon name="search" :size="16"/></span><strong class="amber">{{ openCount }}<small>项</small></strong><p>查看原因与缺失证据</p></div><div class="metric"><span>来源文件 <Icon name="file" :size="16"/></span><strong>{{ overview?.counts.documents??0 }}<small>份</small></strong><p>原始附件可追溯</p></div><div class="metric"><span>可开展检查 <Icon name="shield" :size="16"/></span><strong>{{ availableCount }}<small>/ {{ overview?.capabilities.length??4 }}</small></strong><p>能力随实际资料开放</p></div></div>
      <div class="dashboard-grid"><section class="panel case-panel"><div class="panel-heading"><div><span class="section-number">01</span><h2>需要关注的事项</h2></div><button class="text-button" @click="go('cases')">全部案件 <Icon name="arrow" :size="15"/></button></div><div v-if="latestCases.length" class="issue-list"><button v-for="c in latestCases.slice(0,5)" :key="c.id" class="issue-item" @click="pickCase(c.id)"><span :class="['severity-mark',tone(c.severity)]"/><span class="issue-content"><strong>{{ c.title }}</strong><small>{{ c.explanation }}</small><span class="issue-tags"><span>{{ c.rule_id }}</span><span>{{ c.evidence_ids?.length??0 }} 条引用</span></span></span><span :class="['badge',tone(c.status)]">{{ status(c.status) }}</span><Icon name="chevron" :size="17"/></button></div><div v-else class="empty-panel"><Icon name="search" :size="34"/><h3>{{ overview?.counts.records?'等待首次规则检查':'还没有可检查的资料' }}</h3><p>{{ overview?.counts.records?'点击“执行月结检查”，根据当前快照生成结果。':'可以导入文件，或使用一份完整的合成演示账套。' }}</p><button v-if="!overview?.counts.records" class="button" :disabled="!!busy" @click="seed()">载入合成演示账套 <Icon name="arrow" :size="15"/></button><button v-else class="button" :disabled="!!busy" @click="check">执行检查</button></div><div class="panel-foot"><Icon name="info" :size="14"/><span>“检查通过”只代表已声明规则通过，不代表全部账务正确。</span></div></section>
      <section class="panel readiness-panel"><div class="panel-heading"><div><span class="section-number">02</span><h2>资料就绪度</h2></div><span class="tiny-label">{{ availableCount }} / {{ overview?.capabilities.length??4 }}</span></div><div class="readiness-meter"><NProgress type="circle" :percentage="Math.round(availableCount/(overview?.capabilities.length||4)*100)" :stroke-width="7" color="#2a6857" rail-color="#edf0e9" :height="106"><span class="progress-label">{{ availableCount }}<small>场景可检查</small></span></NProgress><div><strong>{{ availableCount===4?'资料已具备':'按资料边界检查' }}</strong><p>资料不完整时<br/>保留判断并提出补证。</p></div></div><div class="capability-list"><div v-for="cap in overview?.capabilities" :key="cap.name"><span :class="['cap-dot',{ready:cap.available}]"><Icon :name="cap.available?'check':'plus'" :size="12"/></span><span>{{ cap.name }}<small v-if="!cap.available">缺少 {{ cap.missing.map(x=>kindNames[x]||x).join('、') }}</small></span><span class="cap-status">{{ cap.available?'可检查':'待补齐' }}</span></div></div></section>
      <section class="panel"><div class="panel-heading"><div><span class="section-number">03</span><h2>科目余额概览</h2></div><span class="tiny-label">CNY · 借方净额</span></div><BalanceChart v-if="Object.keys(overview?.balances||{}).length" :balances="overview!.balances"/><div v-else class="small-empty">导入分录后展示科目余额。</div></section>
      <section class="snapshot-panel"><div class="eyebrow">A TRACEABLE CLOSE</div><h2>固定证据边界，<br/>再讨论处理结论。</h2><p>每次调查绑定账套、快照和政策版本。新增资料后，旧结论保留，复核需要重新进行。</p><div class="snapshot-code"><Icon name="layers" :size="16"/><span>当前快照</span><code>{{ short(overview?.latest_snapshot_id) }}</code></div><button class="text-button light" @click="go('evidence')">查看证据与来源 <Icon name="arrow" :size="16"/></button></section></div>
      <FundsPanel v-if="bookId" :key="`${bookId}-${overview?.latest_snapshot_id}`" :book-id="bookId" :period="book?.period||''"/>
     </template>

     <template v-else-if="page==='books'">
      <section class="panel"><div class="panel-heading"><div><span class="section-number">01</span><h2>当前账套</h2></div><button class="button" @click="openBook(true)">修改政策配置</button></div><div class="detail-grid"><div><label>账套名称</label><strong>{{ book?.name }}</strong></div><div><label>适用制度</label><strong>{{ framework(book?.framework) }}</strong></div><div><label>会计期间</label><strong class="mono">{{ book?.period }}</strong></div><div><label>政策版本</label><strong class="mono">v{{ book?.version }}</strong></div><div><label>科目范围</label><strong class="mono">{{ book?.accounts.join(' / ') }}</strong></div><div><label>锁定期间</label><strong>{{ book?.locked_periods.join('、')||'未配置' }}</strong></div></div></section>
      <section class="panel spaced"><div class="panel-heading"><div><span class="section-number">02</span><h2>规则覆盖矩阵</h2></div><span class="tiny-label">以已实现规则为边界</span></div><div class="table-wrap"><table><thead><tr><th>规则 / 编号</th><th>适用制度</th><th>状态</th><th>说明与依据</th></tr></thead><tbody><tr v-for="(p,i) in policies" :key="i"><td><strong>{{ p.name||p.title||p.id||p.rule_id }}</strong><small class="block mono">{{ p.id||p.rule_id }}</small></td><td>{{ Array.isArray(p.frameworks)?p.frameworks.map(framework).join(' / '):show(p.framework||'通用') }}</td><td><span :class="['badge',tone(p.status)]">{{ status(p.status||'experimental') }}</span></td><td class="wrap-text">{{ p.description||p.scope||p.conditions||p.limitations||'见规则说明' }}<a v-if="typeof p.source==='string'&&p.source.startsWith('https://')" :href="p.source" target="_blank" rel="noopener noreferrer">查看依据 ↗</a></td></tr><tr v-if="!policies.length"><td colspan="4" class="table-empty">暂无规则目录。</td></tr></tbody></table></div><div class="panel-foot"><Icon name="info" :size="14"/>两套制度分别配置和验证；检索到条款不代表系统已实现该条款。</div></section>
      <PolicyChecks v-if="bookId" :book-id="bookId" :snapshot-id="overview?.latest_snapshot_id??null" :framework="book?.framework==='SCAS'?'SCAS':'CAS'" :records="records"/>
     </template>

     <template v-else-if="page==='imports'">
      <div class="two-columns"><section class="panel upload-panel"><div class="panel-heading"><div><span class="section-number">01</span><h2>上传业务资料</h2></div><span class="tiny-label">最大 20 MB</span></div><label class="upload-zone" tabindex="0" @keydown.enter="fileInput?.click()"><input ref="fileInput" aria-label="业务资料文件" type="file" accept=".csv,.xlsx,.json,.pdf" @change="fileChanged"/><span class="upload-symbol"><Icon name="upload" :size="27"/></span><strong>{{ selectedFile?.name||'点击选择需要导入的文件' }}</strong><span>CSV / XLSX / JSON / 文本 PDF</span><small>先预览字段与错误，再确认导入</small></label><div class="upload-actions"><span>账套：{{ book?.name }}</span><button class="button primary" :disabled="!selectedFile||!!busy" @click="upload">解析与预览 <Icon name="arrow" :size="16"/></button></div></section><section class="demo-panel"><span class="badge warning">合成数据 · 非真实企业</span><h2>从一个有答案的<br/>采购案例开始。</h2><p>10 万元采购、分批收货与付款、重复凭证和迟到资料。所有异常都由数据计算产生。</p><div class="button-row"><button class="button" :disabled="!!busy" @click="seed()">载入演示账套</button><button class="text-button" :disabled="!!busy" @click="seed(true)">补充迟到收货单 <Icon name="plus" :size="14"/></button></div></section></div>
      <OcrReviewPanel v-if="book" :key="`${book.id}-${book.version}`" :book-id="book.id" :period="book.period" :currency="book.currency" @preview="acceptOcrPreview"/>
      <section v-if="preview" class="panel spaced"><div class="panel-heading"><div><span class="section-number">02</span><h2>校验与字段映射</h2></div><span class="badge" :class="preview.errors.length?'danger':'success'">{{ preview.record_count }} 条记录 / {{ preview.errors.length }} 项错误</span></div><p v-if="preview.mapping._origin==='ocr_human_review'" class="caption">来自人工字段复核；修改内容请在扫描件面板新增复核版本。确认导入后才生成业务记录。</p><div v-else class="mapping-grid"><label v-for="(label,key) in fieldLabels" :key="key"><span>{{ label }}</span><select v-model="mapping[key]"><option value="">自动识别 / 未映射</option><option v-for="column in preview.columns" :key="column" :value="column">{{ column }}</option></select></label></div><div class="inline-actions"><button v-if="preview.mapping._origin!=='ocr_human_review'" class="button" :disabled="!!busy" @click="remap">按映射重新校验</button><button class="button primary" :disabled="!!busy||!!preview.errors.length||!preview.record_count||preview.status==='confirmed'" @click="confirmImport">确认导入并建立快照</button></div><div v-if="preview.errors.length" class="validation-errors"><div v-for="(err,i) in preview.errors.slice(0,30)" :key="i"><strong>第 {{ err.row }} 行 · {{ err.field }}</strong><span>{{ err.message }}</span></div></div><div class="table-wrap"><table><thead><tr><th v-for="key in previewDisplayColumns" :key="key">{{ fieldLabels[key]||key }}</th></tr></thead><tbody><tr v-for="(row,i) in previewDisplayRows.slice(0,10)" :key="i"><td v-for="key in previewDisplayColumns" :key="key">{{ show(row[key]) }}</td></tr></tbody></table></div><div class="panel-foot">预览显示前 10 条。缺失金额须修正，不会自动填零。</div></section>
      <section class="panel spaced"><div class="panel-heading"><div><span class="section-number">03</span><h2>导入记录</h2></div><span class="tiny-label">{{ imports.length }} 个批次</span></div><div class="table-wrap"><table><thead><tr><th>批次标识</th><th>记录数</th><th>校验错误</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in imports" :key="item.id"><td class="mono">{{ short(item.id) }}</td><td>{{ item.record_count }}</td><td>{{ item.errors.length }}</td><td><span :class="['badge',tone(item.status)]">{{ status(item.status) }}</span></td><td><button class="text-button" @click="preview=item;mapping={...item.mapping}">查看预览</button></td></tr><tr v-if="!imports.length"><td colspan="5" class="table-empty">导入一份资料，校验结果将保存在这里。</td></tr></tbody></table></div></section>
     </template>

     <template v-else-if="page==='cases'">
      <div class="investigation-layout"><section class="panel case-index"><div class="search-input"><Icon name="search" :size="16"/><input v-model="query" placeholder="搜索异常或规则…" aria-label="搜索异常"/></div><label class="checkbox-row"><input v-model="showHistory" type="checkbox"/>显示历史快照</label><button v-for="c in filteredCases" :key="c.id" :class="['case-option',{selected:selectedId===c.id}]" @click="pickCase(c.id)"><span><span :class="['severity-mark',tone(c.severity)]"/>{{ status(c.severity) }}优先级 <small>{{ short(c.id) }}</small></span><strong>{{ c.title }}</strong><span class="case-option-meta"><span :class="['badge',tone(c.status)]">{{ status(c.status) }}</span><small>{{ c.evidence_ids?.length||0 }} 条引用</small></span></button><div v-if="!filteredCases.length" class="small-empty">当前没有案件。<br/>请先在月结工作台执行检查。</div></section>
      <section v-if="selectedCase" class="panel investigation-detail"><div class="panel-heading"><div><span class="section-number">CASE</span><h2>{{ selectedCase.title }}</h2></div><span :class="['badge',tone(selectedCase.status)]">{{ status(selectedCase.status) }}</span></div><div class="case-metadata"><span class="mono">{{ selectedCase.rule_id }}</span><span>快照 {{ short(selectedCase.snapshot_id) }}</span><span>{{ evidence.length }} 条来源证据</span></div><div v-if="isStale" class="notice warning"><Icon name="clock" :size="18"/>此案件基于历史快照。可查看当时证据，复核前需在最新快照重新检查。</div><p class="finding-text">{{ selectedCase.explanation }}</p><div v-if="selectedCase.missing_evidence?.length" class="missing-evidence"><strong>需要补充的资料</strong><ul><li v-for="(item,i) in selectedCase.missing_evidence" :key="i">{{ item }}</li></ul></div><EvidenceRequests :case-id="selectedCase.id" :evidence="evidence"/><div class="run-controls"><label>调查方式<select v-model="investigationMode" :disabled="isWorking"><option value="rules">确定性规则 · 无需模型</option><option value="single" :disabled="!health?.model_configured">单 Agent + 工具</option><option value="multi" :disabled="!health?.model_configured">固定分工 Multi-Agent</option><option value="active" :disabled="!health?.model_configured">主动调查 Multi-Agent · 实验性</option></select></label><button class="button primary" :disabled="!!busy||isWorking" @click="investigate"><Icon name="search" :size="16"/>{{ isWorking?'调查进行中':'启动调查' }}</button></div><p v-if="investigationMode!=='rules'" class="caption">本次操作将调用已配置的 DeepSeek API，发送必要资料片段并消耗额度。</p><p v-else-if="!health?.model_configured" class="caption">DeepSeek 尚未配置；规则调查可以独立运行。</p><div v-if="selectedCase.runs?.length" class="run-history"><label for="run-history-select">调查记录</label><NSelect id="run-history-select" aria-label="调查记录" :value="run?.id" :options="runOptions" :disabled="isWorking" @update:value="selectRun"/></div><div v-if="run" class="run-result"><div class="section-title"><h3>调查运行</h3><span :class="['badge',tone(run.status)]">{{ status(run.status) }}</span></div><div v-if="isWorking" class="run-working"><NSpin :size="16"/>正在执行真实查询和核验，进度自动更新。</div><div class="timeline"><div v-for="(step,i) in run.steps||[]" :key="i"><span>{{ String(i+1).padStart(2,'0') }}</span><div><strong>{{ step.title||step.name||step.node||step.role||step.step||'执行步骤' }}</strong><p>{{ step.status?status(step.status):show(step.message||step.summary||step.result||step) }}</p></div></div></div><InvestigationPolicyContext :run-id="run.id" :evidence="evidence" :interpretations="run.result?.policy_interpretations" @inspect="inspectEvidence"/><InvestigationResult v-if="run.result?.status" :result="run.result" :evidence="evidence" @inspect="inspectEvidence"/><div v-if="run.error" class="notice error">{{ show(run.error) }}</div></div><div class="detail-bottom-actions"><button class="button" @click="go('evidence')"><Icon name="link" :size="16"/>浏览证据</button><button class="button" @click="beginSimulation"><Icon name="sliders" :size="16"/>模拟处理</button><button class="button primary" @click="go('reviews')">形成复核底稿 <Icon name="arrow" :size="16"/></button></div></section><section v-else class="panel choose-case"><Icon name="search" :size="36"/><h2>选择一个案件开始调查</h2><p>查看具体差异，逐项关联来源资料。</p></section></div>
     </template>

     <template v-else-if="page==='evidence'">
      <section class="panel"><div class="panel-heading"><div><span class="section-number">01</span><h2>案件证据</h2></div><NSelect class="case-select" :value="selectedId" :options="caseOptions" placeholder="选择案件查看证据" @update:value="id=>pickCase(id,'evidence')"/></div><template v-if="selectedCase"><div class="evidence-topline"><span>{{ selectedCase.title }}</span><code>快照 {{ short(selectedCase.snapshot_id) }}</code></div><EvidenceGraph :evidence="evidence" :case-id="selectedCase.id" @select="inspectEvidence"/><div class="table-wrap"><table><thead><tr><th>证据编号</th><th>类型</th><th>来源文件</th><th>定位</th><th>操作</th></tr></thead><tbody><tr v-for="item in evidence" :key="item.id"><td class="mono">{{ short(item.id) }}</td><td>{{ kindNames[item.kind]||item.kind }}</td><td>{{ item.document_name }}</td><td class="wrap-text">{{ show(item.locator) }}</td><td><button class="text-button" @click="inspectEvidence(item)">查看记录 <Icon name="arrow" :size="14"/></button></td></tr></tbody></table></div></template><div v-else class="small-empty">选择一个案件，查看它当时可见的证据。</div></section><section class="panel spaced"><div class="panel-heading"><div><span class="section-number">02</span><h2>全部来源文件</h2></div><span class="tiny-label">校验哈希后下载</span></div><div class="table-wrap"><table><thead><tr><th>文件名</th><th>数据属性</th><th>内容指纹</th><th>操作</th></tr></thead><tbody><tr v-for="doc in documents" :key="String(doc.id)"><td>{{ doc.name }}</td><td><span :class="['badge',doc.synthetic?'warning':'neutral']">{{ doc.synthetic?'合成数据':'用户导入' }}</span></td><td class="mono">{{ String(doc.sha256||'').slice(0,20) }}…</td><td><button v-if="String(doc.name).toLowerCase().endsWith('.pdf')" class="text-button pdf-open-button" @click="previewPdf(doc)">按页预览</button><button class="text-button" @click="action('下载来源文件',()=>download(`/documents/${doc.id}/file`,String(doc.name)))">下载原文件 <Icon name="download" :size="14"/></button></td></tr><tr v-if="!documents.length"><td colspan="4" class="table-empty">没有来源文件。</td></tr></tbody></table></div></section>
     </template>

     <template v-else-if="page==='simulation'">
      <div class="notice neutral"><Icon name="shield"/>模拟仅计算候选调整的影响。原始账簿不变，借贷平衡不等于处理合规。</div><section class="panel"><div class="panel-heading"><div><span class="section-number">01</span><h2>调整草稿</h2></div><NSelect class="case-select" :value="selectedId" :options="caseOptions" placeholder="选择需要模拟的案件" @update:value="id=>pickCase(id,'simulation')"/></div><div v-if="!selectedId" class="small-empty">请先选择案件，模拟将绑定其数据快照。</div><template v-else><div class="form-row simulation-links"><label>关联发票号（可选）<input v-model="simulationLink.invoice_id" placeholder="仅填写已核实的来源编号"/></label><label>关联订单号（可选）<input v-model="simulationLink.order_id"/></label><label>交易对手（可选）<input v-model="simulationLink.counterparty"/></label></div><div class="table-wrap adjustment-table"><table><thead><tr><th>凭证号</th><th>科目</th><th>借方金额</th><th>贷方金额</th><th>业务日期</th><th>会计期间</th><th>操作</th></tr></thead><tbody><tr v-for="(row,i) in adjustmentRows" :key="i"><td><input v-model="row.voucher_id" :aria-label="`第${i+1}行凭证号`"/></td><td><input v-model="row.account" :aria-label="`第${i+1}行科目`"/></td><td><input v-model="row.debit" inputmode="decimal" :aria-label="`第${i+1}行借方金额`"/></td><td><input v-model="row.credit" inputmode="decimal" :aria-label="`第${i+1}行贷方金额`"/></td><td><input v-model="row.business_date" type="date" :aria-label="`第${i+1}行业务日期`"/></td><td><input v-model="row.period" type="month" :aria-label="`第${i+1}行会计期间`"/></td><td><button class="icon-button" :aria-label="`删除第${i+1}行`" :disabled="adjustmentRows.length===1" @click="adjustmentRows.splice(i,1)"><Icon name="close" :size="15"/></button></td></tr></tbody></table></div><div class="inline-actions"><button class="button" @click="addAdjustment"><Icon name="plus" :size="15"/>新增分录</button><button class="button primary" :disabled="!!busy" @click="simulate">计算处理影响 <Icon name="arrow" :size="16"/></button></div></template></section><section v-if="currentSim" class="panel spaced"><div class="panel-heading"><div><span class="section-number">02</span><h2>模拟前后对比</h2></div><span :class="['badge',currentSim.balanced?'success':'danger']">{{ currentSim.balanced?'借贷平衡':'借贷不平衡' }}</span></div><div class="table-wrap"><table><thead><tr><th>科目</th><th class="number">调整前净额</th><th class="number">调整后净额</th><th class="number">变化</th></tr></thead><tbody><tr v-for="account in simAccounts" :key="account"><td class="mono">{{ account }}</td><td class="number">{{ money(currentSim.before[account]) }}</td><td class="number">{{ money(currentSim.after[account]) }}</td><td class="number">{{ money(currentSim.delta[account]) }}</td></tr></tbody></table></div><div class="policy-note"><strong>政策与约束</strong><p>{{ currentSim.policy_note }}</p><div v-for="(v,i) in currentSim.violations" :key="i" class="notice error">{{ show(v) }}</div><p v-if="!currentSim.violations.length" class="text-success">当前已实现约束未发现违规；仍需复核业务适用性。</p><h3>调整后重新检查</h3><p v-if="!currentSim.new_findings?.length">已实现规则未发现差异。</p><div v-for="(finding,i) in currentSim.new_findings||[]" :key="i" class="notice neutral"><strong>{{ finding.title }}</strong><span>{{ status(finding.status) }} · {{ finding.explanation }}</span></div></div></section>
     </template>

     <template v-else-if="page==='reviews'">
      <section class="panel"><div class="panel-heading"><div><span class="section-number">01</span><h2>复核与底稿</h2></div><NSelect class="case-select" :value="selectedId" :options="caseOptions" placeholder="选择要复核的案件" @update:value="id=>pickCase(id,'reviews')"/></div><div v-if="!selectedCase" class="small-empty">选择案件，记录复核意见并导出完整底稿。</div><template v-else><div class="review-paper"><div class="paper-top"><span>LEDGERLENS / REVIEW WORKPAPER</span><code>{{ short(selectedCase.id) }}</code></div><h2>{{ selectedCase.title }}</h2><div class="paper-meta"><span>{{ book?.name }}</span><span>{{ framework(book?.framework) }}</span><span>快照 {{ short(selectedCase.snapshot_id) }}</span></div><h3>发现与依据</h3><p>{{ selectedCase.explanation }}</p><div class="review-statistics"><div><strong>{{ evidence.length }}</strong><span>来源证据</span></div><div><strong>{{ selectedCase.runs?.length||0 }}</strong><span>调查运行</span></div><div><strong>{{ simulations.length }}</strong><span>模拟方案</span></div></div><h3>复核意见</h3><div v-if="isStale" class="notice warning">当前资料或政策已经更新，此快照仅可查看，不能接受新的复核。请重新执行月结检查。</div><div class="form-row"><label>复核结论<select v-model="reviewForm.decision"><option value="reserved">保留意见</option><option value="accepted">接受</option><option value="returned">退回补充</option></select></label></div><label class="form-label">意见与未决事项<textarea v-model="reviewForm.comment" rows="4" maxlength="4000" placeholder="说明复核依据、需要补充的资料或保留意见…"/></label><div class="button-row"><button class="button primary" :disabled="!!busy||isStale" @click="review">保存复核意见</button><button class="button" :disabled="!!busy" @click="exportReport()"><Icon name="download" :size="15"/>导出 Markdown</button><button class="text-button" :disabled="!!busy" @click="exportReport('json')">导出 JSON</button></div><div v-if="selectedCase.reviews?.length" class="review-history"><h3>已保存意见</h3><div v-for="(r,i) in selectedCase.reviews" :key="i"><span :class="['badge',tone(r.decision)]">{{ status(r.decision) }}</span><p>{{ r.comment||'未填写意见' }}</p><small>{{ r.created_at }}</small></div></div><div class="paper-foot">会计复核研究与辅助底稿 · 原始账簿未修改 · 结论以资料和已声明规则覆盖范围为限</div></div></template></section>
     </template>

     <template v-else-if="page==='evaluations'">
      <div class="evaluation-intro"><div><div class="eyebrow">MEASURE, DON'T ASSUME</div><h2>效果来自实验，<br/>不来自 Agent 数量。</h2><p>规则基线、单 Agent、固定多 Agent 与主动补证，<br/>在相同模型、工具和预算条件下比较。</p></div><div class="evaluation-boundaries"><div v-for="(limitation,i) in evaluations?.limitations||[]" :key="i"><span>0{{ i+1 }}</span>{{ limitation }}</div><div v-if="!evaluations?.limitations?.length"><span>01</span>尚无评测报告；运行规则基准后查看实际结果。</div></div></div><section class="panel spaced"><div class="panel-heading"><div><span class="section-number">01</span><h2>规则基准记录</h2></div><span class="tiny-label">{{ evaluations?.runs.length||0 }} 次运行</span></div><div v-if="!evaluations?.runs.length" class="empty-panel"><Icon name="chart" :size="32"/><h3>还没有可报告的规则基准结果</h3><p>点击“运行规则基准”，执行确定性测试集。AI 对照需要显式配置模型和预算。</p></div><div v-for="(item,i) in evaluations?.runs" :key="i" class="evaluation-run"><div><span class="badge neutral">规则基线</span><code>{{ short(item.id) }}</code><span>{{ item.created_at }}</span></div><pre>{{ show(item.result||item) }}</pre></div></section><section class="panel spaced"><div class="panel-heading"><div><span class="section-number">02</span><h2>数据集边界</h2></div></div><div class="policy-note"><p>合成任务用于工程和可控场景验证，公开报告用于文档组件验证。尚未实施的真实企业试点与专业复核不会计入已验证能力。</p><pre>{{ show(evaluations?.dataset_summary||{}) }}</pre><p class="caption">目标数量不代表已完成任务；以每次运行报告中的实际任务数为准。</p></div></section>
      <NumericEvaluation/>
      <RootCauseEvaluation/>
     </template>
    </template>
    <footer class="workspace-footer"><span>账证智核 <i>/</i> Evidence before conclusion.</span><span>原账只读 · 版本可追溯 · 结果有边界</span></footer>
   </div>
  </main>
 </div>
 <NModal v-model:show="showBookModal" preset="card" :title="editingBook?'修改账套政策':'建立新的账套'" class="book-modal" style="width:560px;max-width:calc(100vw - 32px)"><form @submit.prevent="saveBook"><label class="form-label">账套名称<input v-model="bookForm.name" placeholder="例如：青禾商贸 · 演示账套" required maxlength="100"/></label><div class="form-grid"><label class="form-label">适用制度<select v-model="bookForm.framework" :disabled="editingBook"><option value="CAS">企业会计准则</option><option value="SCAS">小企业会计准则</option></select></label><label class="form-label">会计期间<input v-model="bookForm.period" type="month" required/></label></div><label class="form-label">科目范围<input v-model="bookForm.accounts" placeholder="使用逗号分隔，如 1002,1405,2202" required/></label><label class="form-label">锁定期间<input v-model="bookForm.locked_periods" placeholder="选填，如 2026-08,2026-07"/></label><p class="caption">制度在建账后固定。修改政策配置会建立新版本，使已有复核需要重新进行。</p><div v-if="error" class="notice error">{{ error }}</div><div class="modal-actions"><button type="button" class="button" @click="showBookModal=false">取消</button><button class="button primary" :disabled="!!busy" type="submit">{{ busy||'保存账套' }}</button></div></form></NModal>
 <NModal v-model:show="pdfOpen" preset="card" title="来源文件 · PDF 页码定位" style="width:900px;max-width:calc(100vw - 24px)"><DocumentPreview v-if="pdfSource&&pdfOpen" :key="pdfSource.documentId" v-bind="pdfSource"/></NModal>
 <NModal v-model:show="detailOpen" preset="card" title="来源证据详情" style="width:760px;max-width:calc(100vw - 32px)"><template v-if="focusedEvidence"><div class="evidence-detail-meta"><span class="badge neutral">{{ kindNames[focusedEvidence.kind]||focusedEvidence.kind }}</span><span>{{ focusedEvidence.document_name }}</span></div><p class="caption">定位：{{ show(focusedEvidence.locator) }}</p><dl class="record-details"><template v-for="(value,key) in focusedEvidence.record" :key="key"><dt>{{ fieldLabels[key]||key }}</dt><dd>{{ show(value) }}</dd></template></dl><div class="modal-actions"><button class="button" @click="action('下载来源文件',()=>download(`/documents/${focusedEvidence!.document_id}/file`,focusedEvidence!.document_name))"><Icon name="download" :size="15"/>下载原始文件</button><button class="button primary" @click="detailOpen=false">关闭</button></div></template></NModal>
</NConfigProvider>
</template>
